/**
 * DDL do SGBD local (SQLite via node:sqlite).
 *
 * Mesmo modelo 3FN de docs/schema.sql (PostgreSQL), adaptado ao dialeto SQLite:
 *  - INTEGER PRIMARY KEY AUTOINCREMENT  <->  GENERATED BY DEFAULT AS IDENTITY
 *  - RAISE(ABORT, ...) em trigger       <->  função plpgsql com RAISE EXCEPTION
 *  - strftime('%s', ...)                <->  EXTRACT(EPOCH FROM ...)
 *  - horas_trabalhadas como texto 'H.CC' (SQLite não possui DECIMAL exato)
 *
 * Tabelas usam CREATE IF NOT EXISTS (dados persistem); triggers e views são
 * recriadas a cada inicialização para refletir a versão atual do código.
 */

export const MENSAGEM_IMUTABILIDADE = 'Registro de ponto e imutavel conforme Portaria 671/2021';
export const MENSAGEM_JUSTIFICATIVA_IMUTAVEL = 'Justificativa de ajuste e imutavel (trilha de auditoria)';

export const SCHEMA_TABELAS = /* sql */ `
PRAGMA foreign_keys = ON;

-- 1. OBRA (Cadastro Mestre)
CREATE TABLE IF NOT EXISTS OBRA (
    id_obra        INTEGER PRIMARY KEY AUTOINCREMENT,
    codigo_obra    VARCHAR(50)  NOT NULL UNIQUE,
    nome_canteiro  VARCHAR(150) NOT NULL,
    localidade     VARCHAR(100) NOT NULL
);

-- 2. ESCALA_TURNO (Cadastro Mestre)
CREATE TABLE IF NOT EXISTS ESCALA_TURNO (
    id_escala                 INTEGER PRIMARY KEY AUTOINCREMENT,
    descricao_turno           VARCHAR(100) NOT NULL,
    carga_horaria_diaria_min  INTEGER      NOT NULL
        CHECK (carga_horaria_diaria_min > 0 AND carga_horaria_diaria_min <= 720),
    tolerancia_clt_min        INTEGER      NOT NULL DEFAULT 10
        CHECK (tolerancia_clt_min >= 0 AND tolerancia_clt_min <= 10)
);

-- 3. COLABORADOR (Cadastro Mestre) — ESCALA_TURNO (1) --define_jornada--> (1:N)
CREATE TABLE IF NOT EXISTS COLABORADOR (
    id_colaborador        INTEGER PRIMARY KEY AUTOINCREMENT,
    id_escala             INTEGER      NOT NULL,
    matricula             VARCHAR(30)  NOT NULL UNIQUE,
    nome_completo         VARCHAR(150) NOT NULL,
    funcao                VARCHAR(100) NOT NULL,
    hash_template_facial  VARCHAR(255) NOT NULL,
    CONSTRAINT fk_colaborador_escala FOREIGN KEY (id_escala)
        REFERENCES ESCALA_TURNO (id_escala) ON DELETE RESTRICT
);

-- 4. REGISTO_PONTO (Ocorrência Transacional — IMUTÁVEL)
--    OBRA (1) --recebe--> (1:N) ; COLABORADOR (1) --realiza--> (0:N)
CREATE TABLE IF NOT EXISTS REGISTO_PONTO (
    id_registo            INTEGER PRIMARY KEY AUTOINCREMENT,
    id_colaborador        INTEGER      NOT NULL,
    id_obra               INTEGER      NOT NULL,
    data_hora_batida      TIMESTAMP    NOT NULL
        -- formato canônico 'YYYY-MM-DD HH:MM:SS' (IS trata o NULL de strftime como falha)
        CHECK (data_hora_batida IS strftime('%Y-%m-%d %H:%M:%S', data_hora_batida)),
    tipo_batida           VARCHAR(20)  NOT NULL
        CHECK (tipo_batida IN ('ENTRADA', 'SAIDA_ALMOCO', 'VOLTA_ALMOCO', 'SAIDA')),
    confianca_facial      DECIMAL(5,2) NOT NULL
        CHECK (confianca_facial >= 0 AND confianca_facial <= 100),
    sincronizado_offline  BOOLEAN      NOT NULL DEFAULT 0
        CHECK (sincronizado_offline IN (0, 1)),
    CONSTRAINT fk_registo_colaborador FOREIGN KEY (id_colaborador)
        REFERENCES COLABORADOR (id_colaborador) ON DELETE RESTRICT,
    CONSTRAINT fk_registo_obra FOREIGN KEY (id_obra)
        REFERENCES OBRA (id_obra) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_registo_colaborador_data ON REGISTO_PONTO (id_colaborador, data_hora_batida);
CREATE INDEX IF NOT EXISTS idx_registo_obra_data        ON REGISTO_PONTO (id_obra, data_hora_batida);

-- 5. JUSTIFICATIVA_AJUSTE (Auditoria / Retificação) — REGISTO_PONTO (1) --gera_retificacao--> (0:1)
CREATE TABLE IF NOT EXISTS JUSTIFICATIVA_AJUSTE (
    id_ajuste           INTEGER PRIMARY KEY AUTOINCREMENT,
    id_registo          INTEGER      NOT NULL UNIQUE,
    motivo_ajuste       TEXT         NOT NULL CHECK (length(trim(motivo_ajuste)) > 0),
    responsavel_rh      VARCHAR(150) NOT NULL,
    data_hora_registro  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_justificativa_registo FOREIGN KEY (id_registo)
        REFERENCES REGISTO_PONTO (id_registo) ON DELETE RESTRICT
);
`;

export const SCHEMA_TRIGGERS = /* sql */ `
-- Imutabilidade — Portaria MTP nº 671/2021
DROP TRIGGER IF EXISTS trg_registo_ponto_bloqueia_update;
CREATE TRIGGER trg_registo_ponto_bloqueia_update
BEFORE UPDATE ON REGISTO_PONTO
BEGIN
    SELECT RAISE(ABORT, '${MENSAGEM_IMUTABILIDADE}');
END;

DROP TRIGGER IF EXISTS trg_registo_ponto_bloqueia_delete;
CREATE TRIGGER trg_registo_ponto_bloqueia_delete
BEFORE DELETE ON REGISTO_PONTO
BEGIN
    SELECT RAISE(ABORT, '${MENSAGEM_IMUTABILIDADE}');
END;

-- A trilha de auditoria também é append-only
DROP TRIGGER IF EXISTS trg_justificativa_bloqueia_update;
CREATE TRIGGER trg_justificativa_bloqueia_update
BEFORE UPDATE ON JUSTIFICATIVA_AJUSTE
BEGIN
    SELECT RAISE(ABORT, '${MENSAGEM_JUSTIFICATIVA_IMUTAVEL}');
END;

DROP TRIGGER IF EXISTS trg_justificativa_bloqueia_delete;
CREATE TRIGGER trg_justificativa_bloqueia_delete
BEFORE DELETE ON JUSTIFICATIVA_AJUSTE
BEGIN
    SELECT RAISE(ABORT, '${MENSAGEM_JUSTIFICATIVA_IMUTAVEL}');
END;
`;

export const SCHEMA_VIEWS = /* sql */ `
DROP VIEW IF EXISTS vw_espelho_ponto_diario;
CREATE VIEW vw_espelho_ponto_diario AS
WITH batidas_ordenadas AS (
    SELECT
        r.id_registo,
        r.id_colaborador,
        r.tipo_batida,
        r.data_hora_batida,
        r.sincronizado_offline,
        date(r.data_hora_batida) AS data_jornada,
        LEAD(r.tipo_batida) OVER (
            PARTITION BY r.id_colaborador, date(r.data_hora_batida)
            ORDER BY r.data_hora_batida, r.id_registo) AS proximo_tipo,
        LEAD(r.data_hora_batida) OVER (
            PARTITION BY r.id_colaborador, date(r.data_hora_batida)
            ORDER BY r.data_hora_batida, r.id_registo) AS proxima_hora
    FROM REGISTO_PONTO r
),
intervalos AS (
    SELECT
        b.*,
        CASE
            WHEN b.tipo_batida IN ('ENTRADA', 'VOLTA_ALMOCO')
             AND b.proximo_tipo IN ('SAIDA_ALMOCO', 'SAIDA')
            THEN CAST(strftime('%s', b.proxima_hora) AS INTEGER)
               - CAST(strftime('%s', b.data_hora_batida) AS INTEGER)
            ELSE 0
        END AS segundos_trabalhados
    FROM batidas_ordenadas b
),
agregado AS (
    SELECT
        i.id_colaborador,
        i.data_jornada,
        COUNT(*)                                                       AS total_batidas,
        SUM(i.sincronizado_offline)                                    AS batidas_offline,
        SUM(CASE WHEN i.tipo_batida IN ('ENTRADA', 'VOLTA_ALMOCO') THEN 1 ELSE 0 END) AS qtd_marcacoes_entrada,
        SUM(CASE WHEN i.tipo_batida IN ('SAIDA_ALMOCO', 'SAIDA') THEN 1 ELSE 0 END)   AS qtd_marcacoes_saida,
        MIN(i.data_hora_batida)                                        AS primeira_batida,
        MAX(i.data_hora_batida)                                        AS ultima_batida,
        MAX(CASE WHEN i.proximo_tipo IS NULL THEN i.tipo_batida END)   AS tipo_ultima_batida,
        SUM(i.segundos_trabalhados) / 60                               AS minutos_trabalhados,
        COUNT(j.id_ajuste)                                             AS qtd_ajustes
    FROM intervalos i
    LEFT JOIN JUSTIFICATIVA_AJUSTE j ON j.id_registo = i.id_registo
    GROUP BY i.id_colaborador, i.data_jornada
),
calculo AS (
    SELECT
        a.*,
        (a.minutos_trabalhados * 100 + 30) / 60 AS centesimos_trabalhados
    FROM agregado a
)
SELECT
    k.id_colaborador,
    c.matricula,
    c.nome_completo,
    c.funcao,
    e.id_escala,
    e.descricao_turno,
    e.carga_horaria_diaria_min,
    e.tolerancia_clt_min,
    k.data_jornada,
    k.total_batidas,
    k.batidas_offline,
    k.primeira_batida,
    k.ultima_batida,
    k.tipo_ultima_batida,
    k.minutos_trabalhados,
    k.centesimos_trabalhados,
    printf('%d.%02d', k.centesimos_trabalhados / 100, k.centesimos_trabalhados % 100) AS horas_trabalhadas,
    printf('%d.%02d', ((e.carga_horaria_diaria_min * 100 + 30) / 60) / 100,
                      ((e.carga_horaria_diaria_min * 100 + 30) / 60) % 100)          AS carga_horaria_horas,
    k.minutos_trabalhados - e.carga_horaria_diaria_min                                AS saldo_minutos,
    CASE
        WHEN k.tipo_ultima_batida IN ('ENTRADA', 'VOLTA_ALMOCO')
             AND k.data_jornada = date('now', 'localtime')                THEN 'EM_ANDAMENTO'
        WHEN k.qtd_marcacoes_entrada <> k.qtd_marcacoes_saida             THEN 'INCOMPLETA'
        WHEN k.minutos_trabalhados - e.carga_horaria_diaria_min > e.tolerancia_clt_min THEN 'HORA_EXTRA'
        WHEN e.carga_horaria_diaria_min - k.minutos_trabalhados > e.tolerancia_clt_min THEN 'DEBITO'
        ELSE 'CONFORME'
    END                                                                                AS situacao_jornada,
    CASE WHEN k.qtd_ajustes > 0 THEN 1 ELSE 0 END                                      AS possui_ajuste,
    k.qtd_ajustes
FROM calculo k
JOIN COLABORADOR  c ON c.id_colaborador = k.id_colaborador
JOIN ESCALA_TURNO e ON e.id_escala      = c.id_escala;

DROP VIEW IF EXISTS vw_resumo_presenca_obra;
CREATE VIEW vw_resumo_presenca_obra AS
WITH ultima_batida AS (
    SELECT
        r.id_colaborador,
        r.id_obra,
        r.tipo_batida,
        r.data_hora_batida,
        ROW_NUMBER() OVER (
            PARTITION BY r.id_colaborador
            ORDER BY r.data_hora_batida DESC, r.id_registo DESC) AS ordem
    FROM REGISTO_PONTO r
),
presentes AS (
    SELECT u.id_obra, COUNT(*) AS qtd
    FROM ultima_batida u
    WHERE u.ordem = 1
      AND u.tipo_batida IN ('ENTRADA', 'VOLTA_ALMOCO')
      AND date(u.data_hora_batida) = date('now', 'localtime')
    GROUP BY u.id_obra
),
batidas AS (
    SELECT
        r.id_obra,
        SUM(CASE WHEN date(r.data_hora_batida) = date('now', 'localtime') THEN 1 ELSE 0 END) AS batidas_hoje,
        SUM(CASE WHEN r.sincronizado_offline = 1
                  AND date(r.data_hora_batida) = date('now', 'localtime') THEN 1 ELSE 0 END) AS sincronizados_offline_hoje,
        SUM(r.sincronizado_offline)                                                          AS total_sincronizado_offline,
        COUNT(*)                                                                             AS total_batidas
    FROM REGISTO_PONTO r
    GROUP BY r.id_obra
),
ajustes AS (
    SELECT r.id_obra, COUNT(j.id_ajuste) AS qtd
    FROM JUSTIFICATIVA_AJUSTE j
    JOIN REGISTO_PONTO r ON r.id_registo = j.id_registo
    GROUP BY r.id_obra
)
SELECT
    o.id_obra,
    o.codigo_obra,
    o.nome_canteiro,
    o.localidade,
    COALESCE(p.qtd, 0)                         AS colaboradores_presentes,
    COALESCE(b.batidas_hoje, 0)                AS batidas_hoje,
    COALESCE(b.sincronizados_offline_hoje, 0)  AS sincronizados_offline_hoje,
    COALESCE(b.total_sincronizado_offline, 0)  AS total_sincronizado_offline,
    COALESCE(b.total_batidas, 0)               AS total_batidas,
    COALESCE(aj.qtd, 0)                        AS total_ajustes_auditados
FROM OBRA o
LEFT JOIN presentes p  ON p.id_obra  = o.id_obra
LEFT JOIN batidas   b  ON b.id_obra  = o.id_obra
LEFT JOIN ajustes   aj ON aj.id_obra = o.id_obra;
`;
